<template><div class="page"><h1>{{ t('区域地图') }}</h1><div class="row" style="margin:12px 0"><el-select v-model="agent" :placeholder="t('选择经纪人')" style="width:190px"><el-option v-for="u in users" :key="u.id" :value="u.id" :label="u.name"/></el-select><el-input v-model="form.name" :placeholder="t('区域名称')" style="width:160px"/><el-select v-model="mode" style="width:150px"><el-option v-for="m in ['polygon','radius','suburbs']" :key="m" :value="m" :label="t(m)"/></el-select><el-input v-if="mode==='suburbs'" v-model="suburbs" :placeholder="t('区域名（逗号分隔）')" style="width:240px"/><el-input-number v-if="mode==='radius'" v-model="form.radius" :min="1" :max="50000"/><el-button v-if="mode==='polygon'" @click="points=[];draw=true">{{ t('点击地图添加顶点') }}</el-button><el-button v-if="mode==='radius'" @click="draw=true">{{ t('点击地图选中心') }}</el-button><el-button type="primary" @click="save">{{ editing?t('保存修改'):t('创建区域') }}</el-button><el-button v-if="editing" @click="cancel">{{ t('取消') }}</el-button></div><p class="muted">{{ draw?t('点击地图绘制；保存后同步到经纪人设备'):t('产权地块：绿色 · 已登记：金色 · 未登记：灰色') }}</p><div id="admin-map" style="height:530px;border-radius:12px;z-index:0"/><div class="card card-b" style="margin-top:16px"><h3>{{ t('经纪人区域') }}</h3><el-table :data="zones.filter(z=>!route.query.agent||z.ownerId===route.query.agent)"><el-table-column prop="name" :label="t('区域名称')"/><el-table-column :label="t('经纪人')"><template #default="{row}">{{ users.find(u=>u.id===row.ownerId)?.name }}</template></el-table-column><el-table-column :label="t('操作')"><template #default="{row}"><el-button @click="editZone(row)">{{ t('编辑') }}</el-button><el-button type="danger" @click="remove(row)">{{ t('删除') }}</el-button></template></el-table-column></el-table></div><AdminParcelDrawer :parcel="selected" @close="selected=null"/></div></template>
<script setup>import {ref,reactive,onMounted,onBeforeUnmount,watch} from 'vue';import {useRoute} from 'vue-router';import L from 'leaflet';import {api} from '../api';import {t} from '../i18n';import {ElMessage,ElMessageBox} from 'element-plus';import AdminParcelDrawer from '../components/AdminParcelDrawer.vue';const route=useRoute(),users=ref([]),zones=ref([]),agent=ref(''),mode=ref('polygon'),suburbs=ref(''),points=ref([]),draw=ref(false),editing=ref(null),selected=ref(null),form=reactive({name:'',radius:500});let map,parcels,zoneLayer,drawing;const colors=['#c9a227','#2563eb','#dc2626','#16a34a','#8b5cf6'];function paint(){zoneLayer?.clearLayers();zones.value.forEach(z=>{const color=colors[users.value.findIndex(u=>u.id===z.ownerId)%colors.length]||'#c9a227';if(z.pts?.length>=3)L.polygon(z.pts,{color}).addTo(zoneLayer);if(z.center?.length===2)L.circle(z.center,{radius:z.radius,color}).addTo(zoneLayer)});drawing?.clearLayers();if(points.value.length)L.polyline(points.value,{color:'#dc2626'}).addTo(drawing)}async function refresh(){zones.value=await api('admin/zones');paint()}async function loadParcels(){if(!map)return;const b=map.getBounds();const bbox=[b.getWest(),b.getSouth(),b.getEast(),b.getNorth()].join(',');try{const data=await api('admin/properties?bbox='+bbox+'&limit=100');parcels.clearLayers();L.geoJSON(data,{pointToLayer:(f,ll)=>L.circleMarker(ll,{radius:5}),style:f=>({color:f.properties.hasOwner?'#16a34a':f.properties.registered?'#c9a227':'#9ca3af',weight:2}),onEachFeature:(f,layer)=>layer.on('click',async()=>{const rows=await api('admin/properties?q='+encodeURIComponent(f.properties.id));selected.value=rows.find(x=>x.id===f.properties.id)||null})}).addTo(parcels)}catch(e){ElMessage.error(e.message)}}async function save(){try{if(!agent.value||!form.name.trim())throw Error(t('选择经纪人与区域名称'));const data={ownerId:agent.value,name:form.name.trim(),suburbs:null,suburb:null,pts:null,center:null,radius:null,...(mode.value==='suburbs'?{suburbs:suburbs.value.split(',').map(x=>x.trim()).filter(Boolean)}:mode.value==='radius'?{center:points.value[0],radius:form.radius}:{pts:points.value})};if(editing.value){data.version=editing.value.version;await api('admin/zones/'+encodeURIComponent(editing.value.id),{method:'PATCH',body:JSON.stringify(data)})}else await api('admin/zones',{method:'POST',body:JSON.stringify(data)});cancel();await refresh();ElMessage.success(t('已保存'))}catch(e){ElMessage.error(e.message)}}function editZone(z){editing.value=z;agent.value=z.ownerId;form.name=z.name||'';form.radius=z.radius||500;mode.value=z.pts?'polygon':z.center?'radius':'suburbs';points.value=z.pts|| (z.center?[z.center]:[]);suburbs.value=(z.suburbs||[]).join(',');paint()}function cancel(){editing.value=null;draw.value=false;points.value=[];suburbs.value='';form.name='';paint()}async function remove(z){try{await ElMessageBox.confirm(t('确定删除此区域？'));await api('admin/zones/'+encodeURIComponent(z.id),{method:'DELETE'});await refresh()}catch{}}onMounted(async()=>{users.value=(await api('admin/users')).filter(u=>u.role==='agent');agent.value=route.query.agent||users.value[0]?.id||'';map=L.map('admin-map').setView([-27.575,153.06],13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);parcels=L.layerGroup().addTo(map);zoneLayer=L.layerGroup().addTo(map);drawing=L.layerGroup().addTo(map);map.on('moveend',loadParcels);map.on('click',e=>{if(!draw.value)return;if(mode.value==='radius')points.value=[[e.latlng.lat,e.latlng.lng]];else points.value.push([e.latlng.lat,e.latlng.lng]);paint()});await refresh();loadParcels()});onBeforeUnmount(()=>map?.remove());watch(()=>route.query.agent,v=>agent.value=v||agent.value)</script>
